/**
 * Type definitions for the Eliza API
 *
 * Eliza is Yandex's internal Anthropic API proxy that provides
 * quota management and usage tracking.
 */
/**
 * Limit values for a specific period.
 * -1 means unlimited.
 */
export interface ElizaLimits {
    /** Maximum number of requests allowed. -1 = unlimited */
    requests: number;
    /** Maximum cost in USD allowed. -1 = unlimited */
    cost: number;
}
/**
 * Quota information for a specific period type (daily/monthly).
 */
export interface ElizaPeriodQuota {
    daily: ElizaLimits;
    monthly: ElizaLimits;
}
/**
 * Quota data grouped by model or "all" for aggregate limits.
 */
export interface ElizaQuotaData {
    all: ElizaPeriodQuota;
    [modelName: string]: ElizaPeriodQuota;
}
/**
 * Full quota response from Eliza API.
 */
export interface ElizaQuotaResponse {
    quota: ElizaQuotaData;
    pool?: string;
    login?: string;
    account?: string;
}
/**
 * Usage values for a specific period.
 */
export interface ElizaUsageValues {
    /** Number of requests made */
    requests: number;
    /** Total cost in USD */
    cost: number;
}
/**
 * Usage information for a specific period type (daily/monthly).
 */
export interface ElizaPeriodUsage {
    daily: ElizaUsageValues;
    monthly: ElizaUsageValues;
}
/**
 * Usage data grouped by model or "all" for aggregate totals.
 */
export interface ElizaUsageData {
    all: ElizaPeriodUsage;
    [modelName: string]: ElizaPeriodUsage;
}
/**
 * Full usage response from Eliza API.
 */
export interface ElizaUsageResponse {
    usage: ElizaUsageData;
    pool?: string;
    login?: string;
    account?: string;
}
/**
 * Pool configuration accepted by Eliza pool create/update API.
 */
export interface ElizaPoolPayload {
    /** ABC service slug used for pool cost attribution */
    abc: string;
    /** Logins, ABC roles (abc:slug[/scope]), or TVM ids (tvm:123456) allowed to use the pool */
    members: string[];
}
/**
 * Pool details returned by Eliza. The exact response shape is service-defined.
 */
export interface ElizaPoolInfoResponse extends Record<string, unknown> {
    abc?: string;
    members?: string[];
    logins?: string[];
}
/**
 * Response returned by Eliza after pool create/update.
 */
export interface ElizaPoolUpdateResponse extends Record<string, unknown> {
    status: string;
    logins?: string[];
}
/**
 * Calculated balance for a token, including remaining quota and effective balance.
 */
export interface TokenBalance {
    /** Secret key identifier (from SecretRef.key) */
    tokenKey: string;
    /** Optional pool name for Ya-Pool header (uses pool quota instead of personal) */
    poolName?: string;
    /** Remaining daily cost quota (null = unlimited) */
    dailyRemaining: number | null;
    /** Remaining monthly cost quota (null = unlimited) */
    monthlyRemaining: number | null;
    /** Effective balance used for sorting (lowest non-null limit, or Infinity if all unlimited) */
    effectiveBalance: number;
}
/**
 * Input for token selection - token with optional pool configuration.
 */
export interface TokenWithPool {
    /** The API token value */
    token: string;
    /** Secret key identifier (from SecretRef.key) */
    tokenKey: string;
    /** Optional pool name for Ya-Pool header (uses pool quota instead of personal) */
    poolName?: string;
}
/**
 * Result of token selection, including the selected token and its balance info.
 */
export interface TokenSelectionResult {
    /** The API token value to use */
    token: string;
    /** Optional pool name for Ya-Pool header */
    poolName?: string;
    /** Balance information for the selected token */
    balance: TokenBalance;
}
/**
 * Error from Eliza API.
 */
export interface ElizaError {
    code?: string;
    message?: string;
    details?: Record<string, unknown>;
}
